{
  "items": [
    {
      "name": "Real.sum_le_exp_of_nonneg",
      "module_name": "Mathlib.Analysis.Complex.Exponential",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, 0 ≤ x → ∀ (n : ℕ), ∑ i ∈ Finset.range n, x ^ i / ↑i.factorial ≤ Real.exp x"
    },
    {
      "name": "NNReal.summable_geometric",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {r : NNReal}, r < 1 → Summable fun n => r ^ n"
    },
    {
      "name": "Nat.geom_sum_le",
      "module_name": "Mathlib.Algebra.Order.Ring.GeomSum",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 2 ≤ b → ∀ (a n : ℕ), ∑ i ∈ Finset.range n, a / b ^ i ≤ a * b / (b - 1)"
    },
    {
      "name": "pow_add_pow_le'",
      "module_name": "Mathlib.Algebra.Order.Ring.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} [inst : Semiring R] [inst_1 : PartialOrder R] [IsOrderedRing R] {a b : R} {n : ℕ},\n  0 ≤ a → 0 ≤ b → a ^ n + b ^ n ≤ 2 * (a + b) ^ n"
    },
    {
      "name": "tsum_geometric_nnreal",
      "module_name": "Mathlib.Analysis.SpecificLimits.Basic",
      "kind": "theorem",
      "type": "∀ {r : NNReal}, r < 1 → ∑' (n : ℕ), r ^ n = (1 - r)⁻¹"
    }
  ]
}
